'use strict';
const CACHE='parks-field-guide-v3:'+self.registration.scope;
const FILES=["./", "./style.css", "./index.html", "./.nojekyll", "./hub.js", "./parks.json", "./app.js", "./assets/katmai.jpg", "./assets/denali.jpg", "./assets/kenai.jpg", "./assets/grand.jpg", "./assets/death.jpg", "./assets/credits.json", "./assets/page.jpg", "./assets/wrangell.jpg", "./assets/spots/denali-rail.jpg", "./assets/spots/anchorage-center.jpg", "./assets/spots/cabin-nite.jpg", "./assets/spots/brooks-river.jpg", "./assets/spots/denali-center.jpg", "./assets/spots/coastal.jpg", "./assets/spots/road.jpg", "./assets/spots/matanuska.jpg", "./assets/spots/manifest.json", "./assets/spots/culture.jpg", "./assets/spots/fly-denali.jpg", "./assets/spots/dogs.jpg", "./assets/spots/wrangell-center.jpg", "./assets/spots/savage.jpg", "./assets/spots/brooks-falls.jpg", "./assets/spots/ship-creek.jpg", "./parks/wrangell-st-elias/index.html", "./parks/katmai/index.html", "./parks/kenai-fjords/index.html", "./parks/death-valley/index.html", "./parks/denali/index.html", "./parks/grand-canyon/index.html", "./nearby/page/index.html", "./days/anchorage/index.html", "./routes/alaska/index.html", "./routes/southwest/index.html", "./travel/airports/index.html", "./parks/wrangell-st-elias/", "./parks/katmai/", "./parks/kenai-fjords/", "./parks/death-valley/", "./parks/denali/", "./parks/grand-canyon/", "./nearby/page/", "./days/anchorage/", "./routes/alaska/", "./routes/southwest/", "./travel/airports/"];
self.addEventListener('install',e=>e.waitUntil(self.skipWaiting()));
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('message',e=>{if(e.data.type!=='DOWNLOAD')return;e.waitUntil((async()=>{try{const results=await Promise.all(FILES.map(async path=>{const url=new URL(path,self.registration.scope).href;const response=await fetch(url,{cache:'reload'});if(!response.ok)throw new Error('部分檔案未下載完成，請重新嘗試。');return [url,response];}));const cache=await caches.open(CACHE);await Promise.all(results.map(([url,response])=>cache.put(url,response)));e.ports[0].postMessage({ok:true});}catch(err){e.ports[0].postMessage({error:err.message});}})());});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||!e.request.url.startsWith(self.registration.scope))return;e.respondWith((async()=>{try{const response=await fetch(e.request,{cache:'no-cache'});if(response.ok)return response;throw new Error('network');}catch{const cache=await caches.open(CACHE);let cached=await cache.match(e.request,{ignoreSearch:true});if(!cached){const url=new URL(e.request.url);if(url.pathname.endsWith('/index.html'))url.pathname=url.pathname.slice(0,-10);else if(!url.pathname.split('/').pop().includes('.'))url.pathname+='/';cached=await cache.match(url.href,{ignoreSearch:true});}return cached||new Response('請先連線並使用「離線下載」儲存導覽。',{status:503,headers:{'Content-Type':'text/plain;charset=utf-8'}});}})());});
